INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('55555555-0009-0000-0000-000000000005','TCF','22222222-0000-0000-0000-000000000003',NULL,NULL,'A2','STRUCTURE','Complétez : « Hier, Pierre ___ au cinéma avec ses amis. »','Le verbe « aller » se conjugue avec l''auxiliaire « être » au passé composé. À la 3e personne du masculin singulier (« Pierre »), la forme correcte est « est allé ». « A allé » est incorrect car « aller » prend toujours « être » comme auxiliaire. « Va aller » est un futur proche (présent), pas un passé. « Est allée » avec un -e final est la forme féminine, qui ne s''accorde pas avec un sujet masculin.','true','2026-05-27 17:40:30.147221+02','2026-05-27 17:40:30.147221+02','ACTIVE',NULL,NULL,'struct_passe_compose_etre');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('55555555-0009-0000-0000-000000000006','TCF','22222222-0000-0000-0000-000000000003',NULL,NULL,'A2','STRUCTURE','Complétez : « Pour le petit-déjeuner, je prends ___ café et ___ tartines. »','« Café » est masculin singulier, désignant une quantité non précisée : on emploie le partitif « du ». « Tartines » est féminin pluriel : on emploie « des ». « De la » s''emploie devant un féminin singulier (ex. « de la confiture »). « Le » et « les » sont des articles définis (qui désignent quelque chose de précis), inadaptés ici. « Un / une » désignent une unité comptée.','true','2026-05-27 17:40:30.147221+02','2026-05-27 17:40:30.147221+02','ACTIVE',NULL,NULL,'struct_articles_partitifs');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('55555555-0009-0000-0000-000000000007','TCF','22222222-0000-0000-0000-000000000003',NULL,NULL,'A2','STRUCTURE','Remplacez « les clés » par un pronom : « Je ___ prends avant de partir. »','« Les clés » est un complément d''objet direct (COD) au féminin pluriel : il se remplace par le pronom « les », placé avant le verbe « prends ». « Leur » est un pronom indirect (COI) au pluriel (à eux/à elles). « Lui » est un COI singulier (à lui/à elle). « Y » est un pronom qui remplace un complément de lieu ou introduit par « à ».','true','2026-05-27 17:40:30.147221+02','2026-05-27 17:40:30.147221+02','ACTIVE',NULL,NULL,'struct_pronom_cod');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('55555555-0009-0000-0000-000000000008','TCF','22222222-0000-0000-0000-000000000003',NULL,NULL,'A2','STRUCTURE','Complétez : « Mes parents habitent ___ Portugal depuis 2010. »','Devant un nom de pays masculin commençant par une consonne (« le Portugal »), on emploie « au ». On utilise « en » pour les pays féminins (en France, en Italie) ou masculins commençant par une voyelle (en Iran). « À » s''emploie pour les villes (à Paris). « Aux » s''emploie pour les pluriels (aux États-Unis).','true','2026-05-27 17:40:30.147221+02','2026-05-27 17:40:30.147221+02','ACTIVE',NULL,NULL,'struct_preposition_pays');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('55555555-0010-0000-0000-000000000005','TCF','22222222-0000-0000-0000-000000000003',NULL,NULL,'A2','STRUCTURE','Mettez à la forme négative : « Je vois quelque chose. »','Pour nier « quelque chose », on utilise la négation « ne ... rien », qui encadre le verbe : « Je ne vois rien ». « Ne ... personne » nie une personne (« je ne vois personne »). « Ne ... jamais » nie un moment. « Ne ... pas » est une négation générale qui ne remplace pas « quelque chose ».','true','2026-05-27 17:40:30.164849+02','2026-05-27 17:40:30.164849+02','ACTIVE',NULL,NULL,'struct_negation_ne_rien');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('55555555-0010-0000-0000-000000000006','TCF','22222222-0000-0000-0000-000000000003',NULL,NULL,'A2','STRUCTURE','Complétez avec le futur proche : « Demain matin, nous ___ le musée du Louvre. »','Le futur proche se forme avec le verbe « aller » au présent + infinitif. À la 1re personne du pluriel : « allons visiter ». « Avons visité » est un passé composé (action passée). « Visitons » est un présent. « Visiterons » est un futur simple, qui n''est pas le futur proche demandé par la consigne.','true','2026-05-27 17:40:30.164849+02','2026-05-27 17:40:30.164849+02','ACTIVE',NULL,NULL,'struct_futur_proche');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('55555555-0010-0000-0000-000000000007','TCF','22222222-0000-0000-0000-000000000003',NULL,NULL,'A2','STRUCTURE','Complétez : « Mon frère est ___ grand que moi : il mesure dix centimètres de plus. »','Pour exprimer la supériorité avec un adjectif, on utilise « plus ... que » : « plus grand que moi ». « Aussi ... que » exprime l''égalité (même taille), « moins ... que » exprime l''infériorité (il serait plus petit), « autant que » s''emploie avec un verbe ou un nom, pas avec un adjectif.','true','2026-05-27 17:40:30.164849+02','2026-05-27 17:40:30.164849+02','ACTIVE',NULL,NULL,'struct_comparatif');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('55555555-0010-0000-0000-000000000008','TCF','22222222-0000-0000-0000-000000000003',NULL,NULL,'A2','STRUCTURE','Complétez : « Ces fleurs sont vraiment ___. »','L''adjectif s''accorde en genre et en nombre avec le nom qu''il qualifie. « Fleurs » est féminin pluriel : l''adjectif prend la forme féminine pluriel « belles » (le -e marque le féminin, le -s marque le pluriel). « Beau » est masculin singulier, « belle » féminin singulier, « beaux » masculin pluriel.','true','2026-05-27 17:40:30.164849+02','2026-05-27 17:40:30.164849+02','ACTIVE',NULL,NULL,'struct_accord_adjectif');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('55555555-0011-0000-0000-000000000005','TCF','22222222-0000-0000-0000-000000000003',NULL,NULL,'A2','STRUCTURE','Complétez : « J''ai oublié mon livre à la maison. Tu peux me prêter ___ ? »','Pour remplacer « ton livre » (un livre masculin singulier appartenant à « tu »), on utilise le pronom possessif « le tien ». « La tienne » s''emploie pour un nom féminin singulier (la tienne = ta chose). « Les tiens » s''emploie pour un masculin pluriel. « Le mien » désigne ce qui m''appartient (au locuteur), pas à l''interlocuteur.','true','2026-05-27 17:40:30.178875+02','2026-05-27 17:40:30.178875+02','ACTIVE',NULL,NULL,'struct_pronom_possessif');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('55555555-0011-0000-0000-000000000006','TCF','22222222-0000-0000-0000-000000000003',NULL,NULL,'A2','STRUCTURE','Complétez : « Mes cousins ___ chez nous tous les dimanches. »','Le verbe « venir » est irrégulier. À la 3e personne du pluriel du présent : « ils viennent ». « Venent » n''existe pas. « Viens » est la 1re ou 2e personne du singulier. « Venons » est la 1re personne du pluriel.','true','2026-05-27 17:40:30.178875+02','2026-05-27 17:40:30.178875+02','ACTIVE',NULL,NULL,'struct_present_verbes_irreguliers');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('55555555-0011-0000-0000-000000000007','TCF','22222222-0000-0000-0000-000000000003',NULL,NULL,'A2','STRUCTURE','Complétez : « J''habite à Paris ___ trois ans. »','« Depuis » indique un point de départ dans le passé d''une action qui dure encore au moment où l''on parle (j''ai commencé il y a 3 ans et j''y habite toujours). « Pendant » indique une durée terminée ou délimitée (j''ai habité à Paris pendant trois ans = je n''y habite plus). « Pour » indique une durée prévue à l''avance. « Il y a » indique un moment ponctuel dans le passé (je suis arrivé il y a trois ans).','true','2026-05-27 17:40:30.178875+02','2026-05-27 17:40:30.178875+02','ACTIVE',NULL,NULL,'struct_preposition_temps');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('55555555-0011-0000-0000-000000000008','TCF','22222222-0000-0000-0000-000000000003',NULL,NULL,'A2','STRUCTURE','Complétez : « ___ habitez-vous ? — À Lyon. »','La réponse « À Lyon » désigne un lieu : on interroge donc sur le lieu avec « où ». « Quand » interroge sur le moment, « comment » sur la manière, « pourquoi » sur la cause.','true','2026-05-27 17:40:30.178875+02','2026-05-27 17:40:30.178875+02','ACTIVE',NULL,NULL,'struct_mot_interrogatif');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('55555555-0012-0000-0000-000000000005','TCF','22222222-0000-0000-0000-000000000003',NULL,NULL,'A2','STRUCTURE','Complétez : « Mes amis ___ deux enfants. »','Le verbe « avoir » est irrégulier au présent. À la 3e personne du pluriel (« ils/elles ») : « ils ont ». « Avent » n''existe pas. « Ai » est la 1re personne du singulier (j''ai). « Avez » est la 2e personne du pluriel (vous avez).','true','2026-05-27 17:40:30.194289+02','2026-05-27 17:40:30.194289+02','ACTIVE',NULL,NULL,'struct_present_avoir');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('55555555-0012-0000-0000-000000000006','TCF','22222222-0000-0000-0000-000000000003',NULL,NULL,'A2','STRUCTURE','Complétez : « Je vais acheter ___ chaussures, elles sont en solde. »','« Chaussures » est un nom féminin pluriel. L''adjectif démonstratif au pluriel (masculin ou féminin) est « ces ». « Ce » s''emploie devant un masculin singulier (ce livre). « Cette » devant un féminin singulier (cette table). « Cet » devant un masculin singulier commençant par une voyelle ou un h muet (cet homme).','true','2026-05-27 17:40:30.194289+02','2026-05-27 17:40:30.194289+02','ACTIVE',NULL,NULL,'struct_adjectif_demonstratif');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('55555555-0012-0000-0000-000000000007','TCF','22222222-0000-0000-0000-000000000003',NULL,NULL,'A2','STRUCTURE','Complétez : « Je fais du sport ___ par semaine, le mardi et le jeudi. »','La phrase précise que la personne fait du sport « le mardi et le jeudi », soit deux jours par semaine. La fréquence correcte est donc « deux fois ». « Toujours » signifie tout le temps (incompatible avec une fréquence chiffrée précise). « Jamais » est une négation. « Souvent » est vague et ne correspond pas à la précision « le mardi et le jeudi ».','true','2026-05-27 17:40:30.194289+02','2026-05-27 17:40:30.194289+02','ACTIVE',NULL,NULL,'struct_adverbe_frequence');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('55555555-0012-0000-0000-000000000008','TCF','22222222-0000-0000-0000-000000000003',NULL,NULL,'A2','STRUCTURE','Quel est le pluriel de « cheval » dans : « Dans cette ferme, il y a plusieurs ___. »','Les noms masculins se terminant par « -al » forment généralement leur pluriel en « -aux ». « Cheval » → « chevaux ». « Chevals » ne respecte pas cette règle (forme inexistante). « Chevales » n''existe pas non plus. « Cheveux » est le pluriel de « cheveu » (poils sur la tête), pas de « cheval ».','true','2026-05-27 17:40:30.194289+02','2026-05-27 17:40:30.194289+02','ACTIVE',NULL,NULL,'struct_pluriel_noms');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('55555555-0013-0000-0000-000000000013','TCF','22222222-0000-0000-0000-000000000003',NULL,NULL,'A2','STRUCTURE','Complétez : « Ce vélo n''est pas à toi, c''est ___. »','« Vélo » est un nom masculin singulier qui m''appartient (au locuteur) : le pronom possessif correct est « le mien ». « Le tien » désigne ce qui appartient à « tu » (l''interlocuteur, à qui justement on dit que le vélo n''appartient pas). « La mienne » est féminin singulier. « Les miens » est masculin pluriel.','true','2026-05-27 17:40:30.209527+02','2026-05-27 17:40:30.209527+02','ACTIVE',NULL,NULL,'struct_pronom_possessif_mien');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('55555555-0013-0000-0000-000000000014','TCF','22222222-0000-0000-0000-000000000003',NULL,NULL,'A2','STRUCTURE','Complétez : « Le samedi, nous ___ les courses au marché. »','Le verbe « faire » est irrégulier au présent. À la 1re personne du pluriel, la forme correcte est « faisons ». « Fasons » est mal orthographié (forme inexistante). « Faites » est la 2e personne du pluriel (vous faites). « Font » est la 3e personne du pluriel (ils font).','true','2026-05-27 17:40:30.209527+02','2026-05-27 17:40:30.209527+02','ACTIVE',NULL,NULL,'struct_present_faire');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('55555555-0013-0000-0000-000000000015','TCF','22222222-0000-0000-0000-000000000003',NULL,NULL,'A2','STRUCTURE','Complétez : « Dans cette ville, il y a ___ touristes en été. »','L''expression de quantité « beaucoup » s''emploie toujours avec « de » devant un nom, sans article (et sans s) : « beaucoup de touristes ». « Beaucoup des » ne s''emploie que pour désigner un ensemble particulier (beaucoup des touristes que j''ai vus). « Beaucoup les » est incorrect. « Beaucoup » seul ne peut pas précéder directement un nom.','true','2026-05-27 17:40:30.209527+02','2026-05-27 17:40:30.209527+02','ACTIVE',NULL,NULL,'struct_quantite_beaucoup_de');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('55555555-0013-0000-0000-000000000016','TCF','22222222-0000-0000-0000-000000000003',NULL,NULL,'A2','STRUCTURE','Complétez : « J''ai rendez-vous ___ le dentiste cet après-midi. »','Devant le nom d''une personne ou d''un métier (dentiste, médecin, ami), on emploie la préposition « chez ». « À » s''emploie devant un lieu (à la pharmacie) ou une ville (à Paris). « Dans » s''emploie devant un lieu fermé (dans la maison). « Pour » exprime un but ou un destinataire.','true','2026-05-27 17:40:30.209527+02','2026-05-27 17:40:30.209527+02','ACTIVE',NULL,NULL,'struct_preposition_chez');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('55555555-0023-0000-0000-000000000001','TCF','22222222-0000-0000-0000-000000000003',NULL,NULL,'A2','STRUCTURE','Complétez avec la forme correcte du verbe au présent : Mes parents ___ d''Espagne pour Noël.','Le sujet « mes parents » est à la 3e personne du pluriel : « viennent ». La réponse B est correcte. « Vient » est la 3e personne du singulier : c''est un faux ami grammatical (la racine est juste, mais l''accord est faux). « Veulent » est le verbe « vouloir » conjugué, un piège sémantique. « Venir » est l''infinitif, jamais conjugué après un sujet.','true','2026-05-27 17:40:30.278936+02','2026-05-27 17:40:30.278936+02','ACTIVE',NULL,NULL,'struct_present_verbes_irreguliers');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('55555555-0023-0000-0000-000000000002','TCF','22222222-0000-0000-0000-000000000003',NULL,NULL,'A2','STRUCTURE','Complétez avec la forme correcte : Marie ___ à Paris la semaine dernière.','Le verbe « aller » se conjugue avec « être » au passé composé : « est allée ». Avec « être », le participe passé s''accorde avec le sujet : Marie (féminin singulier) → « allée ». La réponse C est correcte. « A allé » est piégeux : un francophone débutant peut confondre les auxiliaires, mais « aller » exige « être ». « Est allé » est piégeux aussi : auxiliaire correct mais accord oublié (Marie est féminin). « Allée » seul n''est pas un verbe conjugué.','true','2026-05-27 17:40:30.278936+02','2026-05-27 17:40:30.278936+02','ACTIVE',NULL,NULL,'struct_passe_compose_etre');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('55555555-0023-0000-0000-000000000003','TCF','22222222-0000-0000-0000-000000000003',NULL,NULL,'A2','STRUCTURE','Complétez avec le futur proche : Demain, nous ___ visiter le musée du Louvre.','Le futur proche se construit avec « aller » au présent + infinitif. Avec « nous » : « allons » + « visiter ». La réponse B est correcte. « Vont » est piégeux : c''est la 3e personne du pluriel, pas la 1ère (« nous »). « Allions » est l''imparfait, ce qui est passé. « Aller visiter » avec l''auxiliaire à l''infinitif est incorrect : il faut conjuguer « aller ».','true','2026-05-27 17:40:30.278936+02','2026-05-27 17:40:30.278936+02','ACTIVE',NULL,NULL,'struct_futur_proche');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('55555555-0023-0000-0000-000000000004','TCF','22222222-0000-0000-0000-000000000003',NULL,NULL,'A2','STRUCTURE','Mettez la phrase à la forme négative : Je mange du pain.','À la négation, « du » devient « de » devant la chose niée : « Je ne mange pas de pain ». La réponse C est correcte. « Je ne mange pas du pain » est un piège classique : la négation impose « de » au lieu de « du ». « Je mange pas de pain » manque le « ne » de la négation soutenue. « Je ne mange du pas pain » est une inversion absurde.','true','2026-05-27 17:40:30.278936+02','2026-05-27 17:40:30.278936+02','ACTIVE',NULL,NULL,'struct_negation');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('55555555-0023-0000-0000-000000000005','TCF','22222222-0000-0000-0000-000000000003',NULL,NULL,'A2','STRUCTURE','Complétez avec les articles corrects : J''aime ___ café, mais ce matin je vais boire ___ thé.','Avec « aimer » on utilise l''article défini (sens général) : « le café ». Pour boire une quantité non précisée d''un liquide, on utilise le partitif : « du thé ». La réponse B est correcte. « du / le » inverse les deux constructions. « du / du » utilise le partitif aussi avec « aimer », ce qui est incorrect (« aimer du café » ne se dit pas). « un / le » utilise un article indéfini avec « aimer » (« j''aime un café » ne se dit pas non plus).','true','2026-05-27 17:40:30.278936+02','2026-05-27 17:40:30.278936+02','ACTIVE',NULL,NULL,'struct_articles');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('55555555-0023-0000-0000-000000000006','TCF','22222222-0000-0000-0000-000000000003',NULL,NULL,'A2','STRUCTURE','Complétez avec l''adjectif « blanc » au bon accord : Les fleurs ___ sentent très bon dans le jardin.','L''adjectif « blanc » s''accorde avec « les fleurs » (féminin pluriel) → « blanches ». La réponse C est correcte. « Blanc » est le masculin singulier : il ne s''accorde pas. « Blancs » est le masculin pluriel : faux ami orthographique très proche de la bonne réponse. « Blanche » est le féminin singulier : accord en genre correct mais pas en nombre.','true','2026-05-27 17:40:30.278936+02','2026-05-27 17:40:30.278936+02','ACTIVE',NULL,NULL,'struct_accord_adjectif');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('55555555-0023-0000-0000-000000000007','TCF','22222222-0000-0000-0000-000000000003',NULL,NULL,'A2','STRUCTURE','Complétez avec la préposition correcte : Cet été, ma sœur va voyager ___ Portugal et ___ Italie.','Devant un pays masculin commençant par une consonne, on utilise « au » : « au Portugal ». Devant un pays féminin, on utilise « en » : « en Italie ». La réponse C est correcte. « En Portugal... en Italie » est un piège classique : la même préposition pour les deux pays est tentante, mais « Portugal » est masculin. « Au Portugal... au Italie » applique « au » partout, ignorant le genre féminin d''« Italie ». « À Portugal... à Italie » utilise la préposition réservée aux villes.','true','2026-05-27 17:40:30.278936+02','2026-05-27 17:40:30.278936+02','ACTIVE',NULL,NULL,'struct_prepositions_lieu');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('55555555-0023-0000-0000-000000000008','TCF','22222222-0000-0000-0000-000000000003',NULL,NULL,'A2','STRUCTURE','Remplacez « ce livre » par le pronom correct : Je lis ce livre → Je ___ lis.','« Ce livre » est un complément d''objet direct masculin singulier → le pronom COD est « le ». La réponse C est correcte. « Lui » est un pronom COI (complément d''objet indirect), utilisé pour des personnes avec une préposition. « La » est le COD féminin singulier (« la maison »). « Y » remplace un complément de lieu (« à Paris ») ou introduit par « à » pour une chose.','true','2026-05-27 17:40:30.278936+02','2026-05-27 17:40:30.278936+02','ACTIVE',NULL,NULL,'struct_pronoms_cod_coi');
